import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteSpaceInvitation } from "../handlers/deleteSpaceInvitation";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { UserPartition } from "../types/UserPartition";

type Data = Awaited<ReturnType<typeof deleteSpaceInvitation>>;
type Vars = { spaceId: SpacePartition; userId: UserPartition };

export function useDeleteSpaceInvitation(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteSpaceInvitation(vars.spaceId, vars.userId),
    ...options,
  });
}
